"""食堂页面 UI 控制器。

已完成 需测试

覆盖游戏 **食堂** (料理/食堂) 页面的导航交互。

使用方式::

    from autowsgr.ui.canteen_page import CanteenPage

    page = CanteenPage(ctrl)
    page.go_back()

批次 4.1.1：菜谱选择、做菜、强制/取消做菜与弹窗关闭全部改为
「识别 → 动作 → 验证」；跳过动画改用画面变化探针 + 稳定帧等待。
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from autowsgr.image_resources import Templates
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui._checkers import confirm_dialog_visible, screen_changed
from autowsgr.ui.stack import record_page_substate
from autowsgr.ui.utils import (
    NavConfig,
    NavigationError,
    click_and_wait_for_page,
    click_and_wait_leave_page,
    wait_for_stable_screen,
)
from autowsgr.vision import ImageChecker, PageMatch
from autowsgr.vision.thresholds import TEMPLATE_PAGE


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.context import GameContext


_log = get_logger('ui')

# ═══════════════════════════════════════════════════════════════════════════════
# 点击坐标
# ═══════════════════════════════════════════════════════════════════════════════

CLICK_BACK: tuple[float, float] = (0.022, 0.058)
"""回退按钮 (◁)，返回后院。

.. note::
    旧代码中食堂 ◁ 按钮可能直接返回主页面 (跨级)，
    具体行为待实际确认。
"""

CLICK_RECIPE: dict[int, tuple[float, float]] = {
    1: (0.3313, 0.5111),
    2: (0.4375, 0.2593),
    3: (0.5792, 0.4019),
}
"""菜谱点击坐标 (1-3)。

换算自旧代码: (318, 276), (420, 140), (556, 217) ÷ (960, 540)。
"""

# ── 做菜弹窗坐标 ──────────────────────────────────────────────────────

CLICK_FORCE_COOK: tuple[float, float] = (0.414, 0.628)
"""「效果正在生效」弹窗中选择继续做菜按钮。

旧代码: timer.relative_click(0.414, 0.628)
"""

CLICK_CANCEL_COOK: tuple[float, float] = (0.650, 0.628)
"""「效果正在生效」弹窗中取消做菜按钮。

旧代码: timer.relative_click(0.65, 0.628)
"""

CLICK_DISMISS_POPUP: tuple[float, float] = (0.788, 0.207)
"""关闭弹窗通用按钮。

旧代码: timer.relative_click(0.788, 0.207)
"""


# ═══════════════════════════════════════════════════════════════════════════════
# 闭环配置 / checker
# ═══════════════════════════════════════════════════════════════════════════════

_RECIPE_CONFIG = NavConfig(
    max_retries=1,
    retry_delay=0.0,
    timeout=4.0,
    interval=0.25,
    stable_frames=2,
)
"""菜谱选择：点击后等待「做菜」按钮出现。"""

_SINGLE_CLICK_CONFIG = NavConfig(
    max_retries=1,
    retry_delay=0.0,
    timeout=3.0,
    interval=0.25,
    stable_frames=1,
)
"""不可逆动作：只点一次，超时只作降级判定。"""


def _cook_button_visible(screen: np.ndarray) -> bool:
    return ImageChecker.template_exists(screen, Templates.Cook.COOK_BUTTON)


def _have_cook_visible(screen: np.ndarray) -> bool:
    return ImageChecker.template_exists(screen, Templates.Cook.HAVE_COOK)


def _popup_visible(screen: np.ndarray) -> bool:
    return (
        ImageChecker.template_exists(screen, Templates.Cook.NO_TIMES)
        or confirm_dialog_visible(screen)
    )


# ═══════════════════════════════════════════════════════════════════════════════
# 页面控制器
# ═══════════════════════════════════════════════════════════════════════════════


class CanteenPage:
    """食堂页面控制器。

    Parameters
    ----------
    ctx:
        游戏上下文。
    """

    def __init__(self, ctx: GameContext) -> None:
        self._ctx = ctx
        self._ctrl = ctx.ctrl

    # ── 页面识别 ──────────────────────────────────────────────────────────

    @staticmethod
    def is_current_page(screen: np.ndarray) -> PageMatch:
        """判断截图是否为食堂页面。

        用食堂页面独有特征模板匹配 (迁移自 classic ``canteen_page``, 86x33
        局部特征), 返回带置信度的 :class:`PageMatch` 供候选集排序。

        Parameters
        ----------
        screen:
            截图 (HxWx3, RGB)。
        """
        detail = ImageChecker.find_best(
            screen, [Templates.Page.CANTEEN], confidence=0.0
        )
        score = detail.confidence if detail is not None else 0.0
        name = PageName.CANTEEN.value
        return PageMatch(
            name=name,
            matched=score >= TEMPLATE_PAGE,
            score=score,
            threshold=TEMPLATE_PAGE,
        )

    # ── 回退 ──────────────────────────────────────────────────────────────

    def go_back(self) -> None:
        """点击回退按钮 (◁)，返回后院。

        Raises
        ------
        NavigationError
            超时仍在食堂页面。
        """
        from autowsgr.ui.backyard_page import BackyardPage

        _log.info('[UI] 食堂 → 返回后院')
        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_BACK,
            checker=BackyardPage.is_current_page,
            source='食堂',
            target='后院',
            stop_event=self._ctx.stop_event,
        )

    # ── 操作 ──────────────────────────────────────────────────────────────

    def select_recipe(self, position: int) -> None:
        """点击选择菜谱，并验证「做菜」按钮已经出现。

        Parameters
        ----------
        position:
            菜谱编号 (1-3)。

        Raises
        ------
        ValueError
            编号不在 1-3 范围内。
        NavigationError
            点击后未出现做菜按钮。
        """
        if position not in CLICK_RECIPE:
            raise ValueError(f'菜谱编号必须为 1-3，收到: {position}')
        _log.info('[UI] 食堂 → 选择菜谱 {}', position)
        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_RECIPE[position],
            checker=_cook_button_visible,
            source=f'食堂-菜谱{position}',
            target='做菜按钮',
            config=_RECIPE_CONFIG,
            stop_event=self._ctx.stop_event,
        )
        record_page_substate(self._ctx, PageName.CANTEEN, f'菜谱{position}')

    def confirm_force_cook(self) -> None:
        """「效果正在生效」弹窗 → 点击继续做菜，并验证弹窗关闭。"""
        _log.info('[UI] 食堂 → 确认继续做菜 (覆盖生效中的菜)')
        click_and_wait_leave_page(
            self._ctrl,
            CLICK_FORCE_COOK,
            _have_cook_visible,
            source='食堂-继续做菜',
            target='效果生效弹窗关闭',
            config=_SINGLE_CLICK_CONFIG,
            stop_event=self._ctx.stop_event,
        )
        self._wait_stable('食堂-继续做菜')

    def cancel_force_cook(self) -> None:
        """「效果正在生效」弹窗 → 取消做菜，并验证弹窗关闭。"""
        _log.info('[UI] 食堂 → 取消做菜 (保留生效中的菜)')
        click_and_wait_leave_page(
            self._ctrl,
            CLICK_CANCEL_COOK,
            _have_cook_visible,
            source='食堂-取消做菜',
            target='效果生效弹窗关闭',
            config=_SINGLE_CLICK_CONFIG,
            stop_event=self._ctx.stop_event,
        )
        self._wait_stable('食堂-取消做菜')

    def dismiss_popup(self) -> None:
        """关闭弹窗 (通用关闭按钮)，并验证弹窗消失。

        当前画面没有已知弹窗时不点击——避免把「无弹窗」当成「已关闭」。
        """
        screen = self._ctrl.screenshot()
        if not _popup_visible(screen):
            _log.debug('[UI] 食堂: 未检测到已知弹窗, 跳过关闭点击')
            return
        _log.info('[UI] 食堂 → 关闭弹窗')
        try:
            click_and_wait_leave_page(
                self._ctrl,
                CLICK_DISMISS_POPUP,
                _popup_visible,
                source='食堂-关闭弹窗',
                target='弹窗消失',
                config=_SINGLE_CLICK_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[UI] 食堂: 点击关闭后弹窗仍在')
        self._wait_stable('食堂-关闭弹窗', timeout=0.8)

    def click_to_skip_animation(self) -> None:
        """点击屏幕右下角跳过做菜动画，并确认画面有可见变化。

        没有专属动画模板，因此用 :func:`screen_changed` 证明点击生效；
        超时只 warning（点一次、不假装已验证），随后等画面稳定。
        """
        _log.info('[UI] 食堂 → 点击跳过动画')
        before = self._ctrl.screenshot()
        try:
            click_and_wait_for_page(
                self._ctrl,
                click_coord=(0.9, 0.9),
                checker=screen_changed(before, min_diff=1.5),
                source='食堂-跳过动画',
                target='画面变化',
                config=_SINGLE_CLICK_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[UI] 食堂: 跳过动画的点击未检测到画面变化')
        self._wait_stable('食堂-跳过动画', timeout=1.5)

    # ── 组合动作 — 做菜 ──

    _COOK_BUTTON_TIMEOUT: float = 7.5

    def _wait_stable(self, source: str, *, timeout: float = 1.2) -> None:
        wait_for_stable_screen(
            self._ctrl,
            timeout=timeout,
            interval=0.12,
            stable_frames=2,
            source=source,
            stop_event=self._ctx.stop_event,
        )

    def cook(self, position: int = 1, *, force_cook: bool = False) -> bool:
        """选择菜谱并做菜。

        必须已在食堂页面。

        Parameters
        ----------
        position:
            菜谱编号 (1-3)。
        force_cook:
            当有菜正在生效时是否继续做菜。

        Returns
        -------
        bool
            做菜是否成功。
        """
        self.select_recipe(position)

        screen = self._ctrl.screenshot()
        detail = ImageChecker.find_template(screen, Templates.Cook.COOK_BUTTON)
        if detail is None:
            raise TimeoutError(f'做菜按钮未出现 ({self._COOK_BUTTON_TIMEOUT}s)')

        before = screen
        clicked = screen_changed(before, min_diff=1.5)
        try:
            click_and_wait_for_page(
                self._ctrl,
                click_coord=detail.center,
                checker=lambda current: (
                    _have_cook_visible(current)
                    or confirm_dialog_visible(current)
                    or clicked(current)
                ),
                source='食堂-开始做菜',
                target='做菜响应',
                config=_SINGLE_CLICK_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError:
            _log.warning('[UI] 食堂: 点击做菜后未确认响应, 继续按画面状态处理')
        self._wait_stable('食堂-做菜响应', timeout=2.0)

        # 检测 "效果正在生效" 弹窗
        screen = self._ctrl.screenshot()
        if _have_cook_visible(screen):
            if force_cook:
                self.confirm_force_cook()
                self._wait_stable('食堂-继续做菜', timeout=1.5)
                if ImageChecker.template_exists(
                    self._ctrl.screenshot(), Templates.Cook.NO_TIMES
                ):
                    self.dismiss_popup()
                    return False
            else:
                self.cancel_force_cook()
                self._wait_stable('食堂-取消做菜', timeout=1.0)
                if _popup_visible(self._ctrl.screenshot()):
                    self.dismiss_popup()
                return False

        self.click_to_skip_animation()
        _log.info('[UI] 做菜完成 (菜谱 {})', position)

        return True
